import {
  CreateBucketCommand,
  DeleteObjectCommand,
  GetObjectCommand,
  HeadBucketCommand,
  PutObjectCommand,
  S3Client
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { infraConfig, type S3Config } from "./config";
import { recordOperation } from "./metrics";

/**
 * S3-compatible object storage (SeaweedFS in development).
 *
 * Object keys are generated by the application, never taken from user input,
 * so a caller cannot traverse into another tenant's prefix. Reads are
 * server-side: a browser receives a short-lived presigned URL, not credentials.
 */

const globalKey = "__naijadealsS3Client" as const;
type GlobalWithS3 = typeof globalThis & { [globalKey]?: S3Client };

function s3Config(): S3Config | null {
  return infraConfig().s3;
}

function client(): S3Client | null {
  const config = s3Config();
  if (!config) return null;

  const scope = globalThis as GlobalWithS3;
  if (!scope[globalKey]) {
    scope[globalKey] = new S3Client({
      region: config.region,
      endpoint: config.endpoint,
      forcePathStyle: config.forcePathStyle,
      credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
    });
  }
  return scope[globalKey]!;
}

export function isStorageConfigured(): boolean {
  return Boolean(s3Config());
}

/** Bucket name comes from configuration, so this cannot create arbitrary buckets. */
export async function ensureBucket(): Promise<boolean> {
  const config = s3Config();
  const s3 = client();
  if (!config || !s3) return false;

  const startedAt = Date.now();
  try {
    await s3.send(new HeadBucketCommand({ Bucket: config.bucket }));
    recordOperation("seaweedfs", "head-bucket", "ok", Date.now() - startedAt);
    return true;
  } catch {
    // A missing bucket is expected on first run; create it, then confirm.
    try {
      await s3.send(new CreateBucketCommand({ Bucket: config.bucket }));
    } catch (createError) {
      const name = (createError as { name?: string }).name ?? "";
      if (!name.includes("BucketAlreadyOwnedByYou") && !name.includes("BucketAlreadyExists")) {
        recordOperation("seaweedfs", "create-bucket", "error", Date.now() - startedAt);
        return false;
      }
    }
    try {
      await s3.send(new HeadBucketCommand({ Bucket: config.bucket }));
      recordOperation("seaweedfs", "create-bucket", "ok", Date.now() - startedAt);
      return true;
    } catch {
      recordOperation("seaweedfs", "create-bucket", "error", Date.now() - startedAt);
      return false;
    }
  }
}

export async function putObject(
  key: string,
  body: Buffer,
  contentType: string
): Promise<{ key: string; bytes: number; etag: string | null } | null> {
  const config = s3Config();
  const s3 = client();
  if (!config || !s3) return null;

  const startedAt = Date.now();
  try {
    const response = await s3.send(
      new PutObjectCommand({
        Bucket: config.bucket,
        Key: key,
        Body: body,
        ContentType: contentType,
        ContentLength: body.byteLength
      })
    );
    recordOperation("seaweedfs", "put", "ok", Date.now() - startedAt);
    return { key, bytes: body.byteLength, etag: response.ETag ?? null };
  } catch {
    recordOperation("seaweedfs", "put", "error", Date.now() - startedAt);
    return null;
  }
}

export async function getObjectBytes(key: string): Promise<Buffer | null> {
  const config = s3Config();
  const s3 = client();
  if (!config || !s3) return null;

  const startedAt = Date.now();
  try {
    const response = await s3.send(new GetObjectCommand({ Bucket: config.bucket, Key: key }));
    if (!response.Body) return null;
    const bytes = Buffer.from(await response.Body.transformToByteArray());
    recordOperation("seaweedfs", "get", "ok", Date.now() - startedAt);
    return bytes;
  } catch {
    recordOperation("seaweedfs", "get", "error", Date.now() - startedAt);
    return null;
  }
}

export async function presignGet(key: string, expiresInSeconds = 300): Promise<string | null> {
  const config = s3Config();
  const s3 = client();
  if (!config || !s3) return null;

  try {
    return await getSignedUrl(s3, new GetObjectCommand({ Bucket: config.bucket, Key: key }), {
      expiresIn: Math.min(Math.max(expiresInSeconds, 30), 3600)
    });
  } catch {
    recordOperation("seaweedfs", "presign", "error", 0);
    return null;
  }
}

export async function deleteObject(key: string): Promise<boolean> {
  const config = s3Config();
  const s3 = client();
  if (!config || !s3) return false;

  const startedAt = Date.now();
  try {
    await s3.send(new DeleteObjectCommand({ Bucket: config.bucket, Key: key }));
    recordOperation("seaweedfs", "delete", "ok", Date.now() - startedAt);
    return true;
  } catch {
    recordOperation("seaweedfs", "delete", "error", Date.now() - startedAt);
    return false;
  }
}

export async function storageHealth(): Promise<boolean> {
  return ensureBucket();
}
